<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useCartStore } from '@/stores/cart'
import { categories, products } from '@ushas/mock-data'
const open = ref(false); const catalogOpen = ref(false); const searchOpen = ref(false); const searchQuery = ref(''); const accountOpen = ref(false); const cart = useCartStore(); const route = useRoute(); const router = useRouter()
const currentUser = ref<{ name: string } | null>(JSON.parse(localStorage.getItem('ushas-demo-user') || 'null'))
const isHome = computed(() => route.path === '/')
const closeMenu = () => { open.value = false; catalogOpen.value = false }
const filteredProducts = computed(() => products.filter(product => `${product.name} ${product.category}`.toLowerCase().includes(searchQuery.value.toLowerCase())).slice(0, 6))
const searchSuggestions = computed(() => ['labiales', 'sombras', 'skincare', 'rubor'].filter(item => item.includes(searchQuery.value.toLowerCase())))
const closeSearch = () => { searchOpen.value = false; searchQuery.value = '' }
const logout = () => { localStorage.removeItem('ushas-demo-user'); currentUser.value = null; accountOpen.value = false; closeMenu(); router.push('/') }
const notices = [
  '10% de descuento en tu primera compra con el código <b>USHAS10</b>',
  'Envío gratis a todo el Perú por compras mayores a <b>S/ 150</b>',
  'Compra segura: productos originales USHAS',
  '¡Nuevos ingresos! Descubre lo último en maquillaje y skincare',
  '¿Compras por mayor? Escríbenos y haz crecer tu negocio con USHAS',
  'Síguenos en redes sociales y entérate primero de nuestras promociones'
]
</script>
<template>
  <div class="announcement" aria-label="Promociones y beneficios"><div class="announcement-track"><template v-for="loop in 2" :key="loop"><span v-for="notice in notices" :key="`${loop}-${notice}`" v-html="notice"></span></template></div></div>
  <header class="header" :class="{ 'header-on-hero': isHome }"><button class="menu" @click="open = true" aria-label="Abrir menú"><span></span><span></span><span></span></button><RouterLink v-if="!isHome" class="brand" to="/">USHAS <small>PERÚ</small></RouterLink><nav><RouterLink to="/categoria/labiales">Labiales</RouterLink><RouterLink to="/categoria/sombras">Sombras</RouterLink><RouterLink to="/catalogo">Accesorios de Belleza</RouterLink><RouterLink to="/categoria/skincare">Skin Care 15% off</RouterLink></nav><div class="actions"><button @click="searchOpen = true" aria-label="Buscar" class="icon-button"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="7.2"/><path d="m16.2 16.2 5 5"/></svg></button><div class="account-menu"><RouterLink v-if="!currentUser" to="/login" aria-label="Iniciar sesión" class="icon-button"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21c.9-4 3.4-6 8-6s7.1 2 8 6"/></svg></RouterLink><button v-else class="icon-button" :aria-expanded="accountOpen" aria-label="Opciones de cuenta" @click="accountOpen = !accountOpen"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21c.9-4 3.4-6 8-6s7.1 2 8 6"/></svg></button><div v-if="currentUser && accountOpen" class="account-popover"><small>Conectada como</small><strong>{{ currentUser.name }}</strong><button @click="logout">Cerrar sesión <span>→</span></button></div></div><span class="bag icon-button" aria-label="Carrito" @click="cart.isOpen = true" style="cursor: pointer;"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8h14l-1.2 13H6.2L5 8Z"/><path d="M9 8V5a3 3 0 0 1 6 0v3"/></svg><i v-if="cart.count">{{ cart.count }}</i></span></div></header>
  <Transition name="search"><section v-if="searchOpen" class="search-panel"><div class="search-box"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="7.2"/><path d="m16.2 16.2 5 5"/></svg><input v-model="searchQuery" autofocus placeholder="Buscar productos"><button v-if="searchQuery" class="clear-search" @click="searchQuery = ''" aria-label="Limpiar">×</button></div><button class="search-close" @click="closeSearch" aria-label="Cerrar búsqueda">×</button><div v-if="searchQuery" class="search-results"><div><h2>Productos</h2><div class="result-grid"><RouterLink v-for="product in filteredProducts" :key="product.id" :to="`/producto/${product.slug}`" @click="closeSearch"><img :src="product.image" :alt="product.name"><div><b>{{ product.name }}</b><span>S/ {{ product.price.toFixed(2) }}</span><small>★★★★★</small></div></RouterLink></div><RouterLink class="view-all" :to="`/catalogo?buscar=${searchQuery}`" @click="closeSearch">VER TODO PARA “{{ searchQuery }}”</RouterLink></div><aside><h2>Sugerencias</h2><button v-for="suggestion in searchSuggestions" :key="suggestion" @click="searchQuery = suggestion">{{ suggestion }}</button><hr><h2>Colecciones</h2><RouterLink v-for="category in categories" :key="category.id" :to="`/categoria/${category.slug}`" @click="closeSearch">{{ category.name }}</RouterLink></aside></div></section></Transition>
  <Transition name="drawer"><aside v-if="open" class="sidebar" aria-label="Menú principal"><div class="sidebar-head"><RouterLink to="/" class="sidebar-brand" @click="closeMenu">USHAS <small>PERÚ</small></RouterLink><button @click="closeMenu" aria-label="Cerrar menú">×</button></div><nav class="sidebar-links"><button class="sidebar-row" @click="catalogOpen = !catalogOpen"><span>Catálogo</span><b :class="{ rotated: catalogOpen }">+</b></button><div v-if="catalogOpen" class="sidebar-subnav"><RouterLink to="/catalogo" @click="closeMenu">Ver todo</RouterLink><RouterLink to="/categoria/labiales" @click="closeMenu">Labiales</RouterLink><RouterLink to="/categoria/sombras" @click="closeMenu">Sombras</RouterLink><RouterLink to="/categoria/rostro" @click="closeMenu">Rostro</RouterLink></div><RouterLink to="/catalogo" @click="closeMenu">Lo más vendido <span>🔥</span></RouterLink><RouterLink to="/afiliados" @click="closeMenu">Creadoras de contenido</RouterLink><RouterLink to="/contacto" @click="closeMenu">Contacto</RouterLink></nav><div class="sidebar-footer"><RouterLink v-if="!currentUser" to="/login" @click="closeMenu">Iniciar sesión</RouterLink><div v-else class="sidebar-account"><small>SESIÓN ACTIVA</small><b>{{ currentUser.name }}</b><button @click="logout">Cerrar sesión <span>→</span></button></div><RouterLink to="/afiliados" @click="closeMenu">Afiliados</RouterLink><RouterLink to="/compras-por-mayor" @click="closeMenu">Compras por Mayor</RouterLink><RouterLink to="/preguntas-frecuentes" @click="closeMenu">Preguntas frecuentes</RouterLink><RouterLink to="/sobre-nosotros" @click="closeMenu">Sobre nosotros</RouterLink><a href="https://wa.me/51912341783" target="_blank" rel="noopener">WhatsApp</a></div></aside></Transition><Transition name="fade"><button v-if="open" class="sidebar-backdrop" aria-label="Cerrar menú" @click="closeMenu"></button></Transition>
  <Transition name="cart-drawer"><aside v-if="cart.isOpen" class="sidebar cart-sidebar" aria-label="Carrito de compras"><div class="sidebar-head"><span class="cart-title">Tu carrito</span><button @click="cart.isOpen = false" aria-label="Cerrar carrito">×</button></div><div class="cart-body"><template v-if="cart.count === 0"><div class="cart-empty"><svg viewBox="0 0 24 24" class="empty-icon"><path d="M5 8h14l-1.2 13H6.2L5 8Z" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M9 8V5a3 3 0 0 1 6 0v3" fill="none" stroke="currentColor" stroke-width="1.5"/></svg><p>Tu carrito está vacío</p><button class="button dark cart-continue" @click="cart.isOpen = false">CONTINUAR COMPRANDO</button><div class="cart-login-prompt" v-if="!currentUser"><p>¿Tienes una cuenta?</p><p><RouterLink to="/login" @click="cart.isOpen = false">Inicia sesión</RouterLink> para pagar más rápido.</p></div></div></template><template v-else><div class="cart-items"><div v-for="(item, index) in cart.items" :key="index" class="cart-item"><img :src="item.image" :alt="item.name"><div class="cart-item-info"><b>{{ item.name }}</b><span>S/ {{ item.price.toFixed(2) }}</span></div></div></div><div class="cart-footer"><div class="cart-total"><span>Total</span> <b>S/ {{ cart.total.toFixed(2) }}</b></div><RouterLink to="/checkout" class="button dark cart-checkout" @click="cart.isOpen = false; cart.checkout = () => {}">PAGAR</RouterLink></div></template></div></aside></Transition><Transition name="fade"><button v-if="cart.isOpen" class="sidebar-backdrop" aria-label="Cerrar carrito" @click="cart.isOpen = false"></button></Transition>
</template>
